import React, { useRef, useEffect, useState } from 'react';
import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import Alert from '@mui/material/Alert';

const MODEL_URL = 'https://cdn.jsdelivr.net/gh/justadudewhohacks/face-api.js@0.22.2/weights/';

export default function Camera() {
    const videoRef = useRef(null);
    const canvasRef = useRef(null);
    const displaySizeRef = useRef(null);
    const rafRef = useRef(null);
    const [error, setError] = useState(null);
    const [status, setStatus] = useState('Loading face detection models...');

    useEffect(() => {
        let cancelled = false;

        (async () => {
            try {
                await Promise.all([
                    faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL),
                ]);
                if (cancelled) return;
                setStatus('Starting camera...');

                const stream = await navigator.mediaDevices.getUserMedia({ video: true });
                if (cancelled) return;
                const video = videoRef.current;
                if (!video) return;
                video.srcObject = stream;

                await new Promise((resolve) => {
                    video.addEventListener('loadedmetadata', resolve, { once: true });
                });

                if (cancelled) return;
                video.play();

                const { videoWidth, videoHeight } = video;
                const canvas = canvasRef.current;
                const displaySize = { width: videoWidth, height: videoHeight };
                displaySizeRef.current = displaySize;

                faceapi.matchDimensions(canvas, displaySize);

                setStatus('Detecting faces...');
                detectLoop();
            } catch (err) {
                if (!cancelled) setError(err.message);
            }
        })();

        function detectLoop() {
            if (cancelled) return;
            const video = videoRef.current;
            const canvas = canvasRef.current;
            if (!video || !canvas || video.readyState < 2) {
                rafRef.current = requestAnimationFrame(detectLoop);
                return;
            }

            faceapi
                .detectAllFaces(video, new faceapi.TinyFaceDetectorOptions({ inputSize: 320 }))
                .then((detections) => {
                    const ctx = canvas.getContext('2d');
                    ctx.clearRect(0, 0, canvas.width, canvas.height);

                    const displaySize = displaySizeRef.current;
                    const resized = faceapi.resizeResults(detections, displaySize);

                    resized.forEach((d) => {
                        const box = d.detection.box;
                        ctx.strokeStyle = '#00ff00';
                        ctx.lineWidth = 3;
                        ctx.strokeRect(box.x, box.y, box.width, box.height);
                    });

                    rafRef.current = requestAnimationFrame(detectLoop);
                })
                .catch(() => {
                    rafRef.current = requestAnimationFrame(detectLoop);
                });
        }

        return () => {
            cancelled = true;
            if (rafRef.current) cancelAnimationFrame(rafRef.current);
            if (videoRef.current?.srcObject) {
                videoRef.current.srcObject.getTracks().forEach((t) => t.stop());
            }
        };
    }, []);

    return (
        <Box sx={{ p: 3, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
            <Typography variant="h5">Facial Recognition</Typography>
            {error && <Alert severity="error">{error}</Alert>}
            {!error && <Typography>{status}</Typography>}
            <Box sx={{ position: 'relative', display: 'inline-block' }}>
                <Box
                    component="video"
                    ref={videoRef}
                    autoPlay
                    muted
                    playsInline
                    sx={{ display: 'block', transform: 'scaleX(-1)' }}
                />
                <Box
                    component="canvas"
                    ref={canvasRef}
                    sx={{
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        transform: 'scaleX(-1)',
                    }}
                />
            </Box>
        </Box>
    );
}

